int read_from_socket(int s, void* arg, int* len) {
    int header;
    if (recv(s, &header, sizeof(int), 0) <= 0) {
        return -1;
    }

    int data_length = ntohl(header);
    if (data_length < 0) {
        return -1;
    }

    if (len) {
        *len = data_length;
    }

    if (data_length > 0) {
        if (recv(s, arg, data_length, 0) < data_length) {
            return -1;
        }
    }

    int data_type;
    if (recv(s, &data_type, sizeof(int), 0) <= 0) {
        return -1;
    }

    return data_type;
}

