    int header;
    if (recv(s, &header, sizeof(int), 0) <= 0) {
        return -1;
    }

    int data_len = ntohl(header);
    if (data_len < 0) {
        return -1;
    }

    *len = data_len;

    if (data_len > 0) {
        int bytes_received = recv(s, arg, data_len, 0);
        if (bytes_received <= 0 || bytes_received != data_len) {
            return -1;
        }
    }

    return ((char*)&header)[0];
}

