        return -1;
    }

    int data_length = ntohl(header);
    if (data_length < 0) {
        return -1;
    }

    if (len != NULL) {
        *len = data_length;
    }

    if (data_length > 0) {
        int bytes_received = recv(s, arg, data_length, 0);
        if (bytes_received <= 0) {
            return -1;
