}

int read_socket_data(int s, void* arg, int* len) {
    int header;
    if (recv(s, &header, sizeof(int), 0) <= 0) {
        return -1;
    }

    int data_length = ntohl(header);
    if (data_length < 0) {
        return -1;
    }

    *len = data_length;

    if (data_length > 0) {
        int total_read = 0;
        char* buffer = (char*)arg;

        while (total_read < data_length) {
            int bytes_read = recv(s, buffer + total_read, data_length - total_read, 0);
            if (bytes_read <= 0) {
                return -1;
            }
            total_read += bytes_read;
        }
    }

    // Assuming the type is stored in the header (e.g., part of the network protocol)
    return (data_length != 0) ? ((int*)arg)[0] : -1;
}
